INSERT INTO wiki_state (slug, id, sort, faction_id, name, name_ko, government, government_ko, power, power_ko, cause, cause_ko, ruler, ruler_ko, capital, capital_ko, base, base_ko) VALUES ('government','government',0,'government','The Government','정부','Paper ministries and multiparty democracy of the old republic; in practice only the OMO Party and the Claw Party remain, a modern feudal system','서류상으로는 옛 대한민국의 부처와 다당제를 유지하나 실제로는 OMO당과 클로당 두 당뿐인 현대 봉건제','14 duchies','14개 공작령','Remnant administration north of the Han River after the Great Blackout; only people written in its ledger count as citizens','대정전 이후 한강 이북의 잔존 행정으로, 장부에 기록된 사람만 국민으로 인정한다','President for Life, elected by the Senators','종신 대통령 — 상원의원들이 선출','Gwanghwamun','광화문','Gangbuk Centered on Cheongwadae','청와대를 중심으로 한 강북');
INSERT INTO wiki_state (slug, id, sort, faction_id, name, name_ko, government, government_ko, power, power_ko, cause, cause_ko, ruler, ruler_ko, capital, capital_ko, base, base_ko) VALUES ('free-city','free-city',1,'free-city','Free City','자유도시','A union of independent city-states in the manner of the Greek poleis; each city holds its own duchy and there is no king','그리스 폴리스처럼 독립한 도시국가들의 연합으로 도시마다 각자 공작령을 쥐며 왕은 없다','7 duchies','7개 공작령','Engineer cities trading goods and skills south of the Han River after the Great Blackout','대정전 이후 한강 이남에서 물자와 기술을 주고받는 엔지니어 도시들','No king; each city is its own power','왕 없음 — 도시마다 각자 권력','Yangpyeong','양평','Western Area South of the Han River','한강 이남 서부');
INSERT INTO wiki_state (slug, id, sort, faction_id, name, name_ko, government, government_ko, power, power_ko, cause, cause_ko, ruler, ruler_ko, capital, capital_ko, base, base_ko) VALUES ('arc','arc',2,'arc','Arc','Arc','A theocratic hierarchy led by the Hierophant Go Ye-jin, in the manner of a Shia clan government','교주 고예진을 정점으로 둔 신권 체제로 시아파식 가문 통치를 따른다','4 duchies','4개 공작령','Around 2122 the Gangnam shelters united under the name Arc','2122년 무렵 강남 대피소들이 아크라는 이름으로 묶였다','Go Ye-jin (Hierophant, Messiah)','고예진 (교주·메시아)','Samseong','삼성','Gangnam Area South of the Han River','한강 이남 강남지역');
